create table if not exists public.prescription_items(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,prescription_id bigint not null references public.prescriptions(id) on delete cascade,product_id bigint references public.products(id) on delete set null,medicine_name_extracted text,dosage text,frequency text,duration text,quantity integer not null default 1,notes text,is_approved boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists prescription_items_prescription_idx on public.prescription_items(business_id,prescription_id);
alter table public.prescription_items enable row level security; revoke all on public.prescription_items from anon,authenticated; grant select,insert,update,delete on public.prescription_items to authenticated;
create policy prescription_items_tenant on public.prescription_items for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_prescription_item_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from prescriptions p where p.id=new.prescription_id and p.business_id=new.business_id) then raise exception 'prescription does not belong to business'; end if; if new.product_id is not null and not exists(select 1 from products p where p.id=new.product_id and p.business_id=new.business_id) then raise exception 'product does not belong to business'; end if; if new.quantity<=0 then raise exception 'quantity must be positive'; end if; return new; end$$;
revoke all on function private.enforce_prescription_item_business() from public,anon,authenticated;
create trigger trg_prescription_item_business before insert or update on public.prescription_items for each row execute function private.enforce_prescription_item_business();
create trigger trg_prescription_items_updated_at before update on public.prescription_items for each row execute function public.touch_updated_at();